"use client";

import { useMemo, useState } from "react";
import { ActionForm } from "@/components/action-form";
import { Badge, Button } from "@/components/ui";
import { variantKey, type ModelRow, type VariantView } from "@/generation/model-comparison-types";
import { PACKAGING_LABELS } from "@/domain/generation/models/matrix";
import { createCandidateSet } from "@/server/candidate-actions";

/**
 * Model comparison for ONE shot (Phase 2E): fit, what each model receives, cost and human history, with a
 * multi-select that builds a candidate set. Nothing is generated by ticking a box; the explicit confirmation
 * of the displayed maximum total is the only thing that submits.
 *
 * Phase 2G.2: with `purpose="production_frame"` the same panel compares the STILL-IMAGE models for a Production
 * Frame candidate set. There is no duration or audio, each model shows the provider canvas it would use and the
 * explicit quality (and so the price) it would request, and one candidate is one image.
 *
 * Phase 2H: with `purpose="animate_production_frame"` it compares the VIDEO models as image-to-video from the Shot's
 * canonical Production Frame: per model, eligible or blocked and why, exact first frame, production / provider /
 * delivery duration, provider canvas, audio conditioning, native audio (default OFF), cost, and the references a
 * keyframe-only model will not receive. No model is pre-selected.
 */
type SortKey = "recommended" | "cost" | "history" | "fit";

const TONE: Record<string, "pass" | "warn" | "fail" | "neutral" | "accent" | "info"> = {
  supported: "pass",
  adaptation_required: "warn",
  unsupported: "fail",
  unknown: "neutral",
};
const REC_TONE: Record<string, "pass" | "warn" | "fail" | "neutral" | "accent" | "info"> = {
  recommended: "accent",
  worth_trying: "info",
  unknown: "neutral",
  poor_historical_fit: "fail",
  incompatible: "fail",
  unavailable: "neutral",
};
const REC_TEXT: Record<string, string> = {
  recommended: "Recommended",
  worth_trying: "Worth trying",
  unknown: "Unknown",
  poor_historical_fit: "Poor historical fit",
  incompatible: "Incompatible",
  unavailable: "Not available here",
};
const PACK_TONE: Record<string, "pass" | "warn" | "fail" | "neutral" | "info"> = {
  used: "pass",
  adapted: "info",
  supported_not_used: "neutral",
  not_used_mode: "warn",
  unsupported: "fail",
  omitted_limit: "fail",
};

const money = (n: number | null) => (n == null ? "unknown" : `$${n.toFixed(n < 1 ? 3 : 2)}`);
const msText = (ms: number | null | undefined) => (ms == null ? "—" : `${Number((ms / 1000).toFixed(2))} s`);

interface Choice {
  mode: "keyframes" | "references" | null;
  tier: string | null;
  audio: boolean;
  /** Still-image quality (Production Frame candidates); null = the model has none. */
  quality: string | null;
}

export function ModelComparePanel({
  projectSlug,
  shotId,
  rows,
  historyNote,
  profileLabel,
  preference,
  coldStart,
  engineVersion,
  maxCandidates,
  setCeilingUsd,
  paidEnabled,
  purpose = "shot_output",
}: {
  projectSlug: string;
  shotId: string;
  /**
   * `production_frame`: still-image candidates for the Shot's Production Frame. `animate_production_frame`: video
   * candidates starting from that frame (Phase 2H).
   */
  purpose?: "shot_output" | "production_frame" | "animate_production_frame";
  rows: ModelRow[];
  historyNote: string;
  profileLabel: string;
  preference: string;
  coldStart: boolean;
  engineVersion: string;
  maxCandidates: number;
  setCeilingUsd: number | null;
  paidEnabled: boolean;
}) {
  const [sort, setSort] = useState<SortKey>("recommended");
  const [picked, setPicked] = useState<Record<string, boolean>>({});
  const [choice, setChoice] = useState<Record<string, Choice>>({});
  const [openKey, setOpenKey] = useState<string | null>(null);
  const [ack, setAck] = useState(false);
  const [confirmTotal, setConfirmTotal] = useState(false);
  const still = purpose === "production_frame";
  const animate = purpose === "animate_production_frame";
  const noun = still ? "image" : animate ? "clip" : "candidate";

  const choiceOf = (r: ModelRow): Choice => {
    const dv = r.variants[r.defaultVariant]!;
    void dv;
    return (
      choice[r.key] ?? {
        mode: r.modes[0] ?? null,
        tier: r.tiers[0] ?? null,
        audio: false,
        quality: r.defaultQuality,
      }
    );
  };
  const variantOf = (r: ModelRow): VariantView => {
    const c = choiceOf(r);
    return r.variants[variantKey(c.mode, c.tier, c.audio, c.quality)] ?? r.variants[r.defaultVariant]!;
  };

  const sorted = useMemo(() => {
    const list = [...rows];
    const rank = (r: ModelRow) => r.recommendation.rank ?? 999;
    const cost = (r: ModelRow) => r.variants[r.defaultVariant]?.estimateUsd ?? Number.POSITIVE_INFINITY;
    list.sort((a, b) => {
      if (sort === "cost") return cost(a) - cost(b);
      if (sort === "history")
        return (
          (b.recommendation.historicalRate ?? -1) - (a.recommendation.historicalRate ?? -1) ||
          rank(a) - rank(b)
        );
      if (sort === "fit")
        return (b.variants[b.defaultVariant]?.fitScore ?? 0) - (a.variants[a.defaultVariant]?.fitScore ?? 0);
      return rank(a) - rank(b);
    });
    return list;
  }, [rows, sort]);

  const selected = rows.filter((r) => picked[r.key]);
  const selectedViews = selected.map((r) => ({ row: r, view: variantOf(r) }));
  const anyBlocked = selectedViews.some(
    (s) => s.view.status === "unsupported" || !s.row.available || s.view.blockers.length > 0,
  );
  const paid = selectedViews.filter((s) => s.row.kind === "real");
  const unknownCost = paid.some((s) => s.view.estimateUsd == null);
  const total = paid.reduce((a, s) => a + (s.view.estimateUsd ?? 0), 0);
  const totalRounded = Math.round(total * 10_000) / 10_000;
  const overCeiling = paid.length > 0 && setCeilingUsd != null && totalRounded > setCeilingUsd;
  const paidBlocked = paid.length > 0 && (!paidEnabled || setCeilingUsd == null);
  const allIgnored = selectedViews.flatMap((s) =>
    s.view.packaging
      .filter((p) => p.state === "unsupported" || p.state === "not_used_mode")
      .map((p) => `${s.row.label}: ${p.label}`),
  );
  const canSubmit =
    selected.length >= 1 &&
    selected.length <= maxCandidates &&
    !anyBlocked &&
    !paidBlocked &&
    !overCeiling &&
    !unknownCost &&
    ack &&
    (paid.length === 0 || confirmTotal);

  const selections = JSON.stringify(
    selected.map((r) => {
      const c = choiceOf(r);
      return {
        provider: r.provider,
        modelId: r.modelId,
        inputMode: c.mode,
        tierId: c.tier,
        nativeAudio: c.audio,
        ...(still ? { quality: c.quality } : {}),
      };
    }),
  );

  return (
    <div className="space-y-3" data-testid="model-compare" data-purpose={purpose}>
      {still ? (
        <p className="text-[12px] text-muted" data-testid="pf-compare-intro">
          Compare still-image models for this Shot&apos;s Production Frame. Each candidate is ONE image from
          ONE model; nothing here changes the Shot, and no image becomes the Production Frame until you choose
          it. Image-to-video later uses whichever frame you make canonical.
        </p>
      ) : null}
      {animate ? (
        <p className="text-[12px] text-muted" data-testid="animate-compare-intro">
          Compare video models for animating this Production Frame. Every candidate starts from the SAME frame
          as its exact first frame (image-to-video); a model that cannot do that is incompatible, never a
          text-to-video fallback. Provider audio stays off unless you turn it on. Nothing is generated until
          you create the set.
        </p>
      ) : null}
      <div className="flex flex-wrap items-center gap-3 text-[11px] text-muted">
        <span>
          Shot profile: <span className="text-fg">{profileLabel}</span>
        </span>
        <span data-testid="history-note">{historyNote}</span>
        <span className="text-faint">
          engine {engineVersion} · {preference.replace("_", " ")}
          {coldStart ? " · cold start" : ""}
        </span>
        <label className="ml-auto flex items-center gap-1.5">
          Sort
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value as SortKey)}
            aria-label="Sort models"
            data-testid="model-sort"
            className="!w-auto"
          >
            <option value="recommended">Recommended</option>
            <option value="cost">Cost</option>
            <option value="history">Historical approval</option>
            <option value="fit">Capability fit</option>
          </select>
        </label>
      </div>

      <div className="overflow-x-auto border border-line">
        <table className="w-full min-w-[980px] border-collapse text-[12px]" data-testid="model-matrix">
          <thead>
            <tr className="border-b border-line bg-panel2 text-left text-[10.5px] uppercase tracking-wide text-muted">
              <th className="px-2 py-1.5">Compare</th>
              <th className="px-2 py-1.5">Model</th>
              <th className="px-2 py-1.5">{animate ? "Eligible" : "Fit"}</th>
              {animate ? (
                <>
                  <th className="px-2 py-1.5">Exact first frame</th>
                  <th className="px-2 py-1.5">Duration (production → provider → delivery)</th>
                  <th className="px-2 py-1.5">Provider canvas</th>
                  <th className="px-2 py-1.5">Audio conditioning</th>
                  <th className="px-2 py-1.5">Native audio</th>
                </>
              ) : (
                <>
                  <th className="px-2 py-1.5">References used</th>
                  {still ? (
                    <th className="px-2 py-1.5">Provider canvas</th>
                  ) : (
                    <th className="px-2 py-1.5">Duration</th>
                  )}
                  <th className="px-2 py-1.5">Framing</th>
                  {still ? null : <th className="px-2 py-1.5">Audio</th>}
                </>
              )}
              <th className="px-2 py-1.5 text-right">Est. cost</th>
              {animate ? <th className="px-2 py-1.5">References omitted (keyframe mode)</th> : null}
              <th className="px-2 py-1.5">Historical fit</th>
              <th className="px-2 py-1.5">Advice</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((r) => {
              const v = variantOf(r);
              const c = choiceOf(r);
              const open = openKey === r.key;
              return (
                <RowFragment key={r.key}>
                  <tr
                    className="border-b border-line align-top"
                    data-testid="model-row"
                    data-model={r.modelId}
                    data-status={v.status}
                    data-rec={r.recommendation.label}
                  >
                    <td className="px-2 py-1.5">
                      <input
                        type="checkbox"
                        aria-label={`Compare ${r.label}`}
                        data-testid="model-pick"
                        checked={Boolean(picked[r.key])}
                        disabled={!r.available || v.status === "unsupported"}
                        onChange={(e) => setPicked((s) => ({ ...s, [r.key]: e.target.checked }))}
                      />
                    </td>
                    <td className="px-2 py-1.5">
                      <button
                        type="button"
                        className="text-left font-medium hover:underline"
                        aria-expanded={open}
                        onClick={() => setOpenKey(open ? null : r.key)}
                      >
                        {r.label}
                      </button>
                      <div className="text-[10.5px] text-faint">
                        {r.providerName}
                        {r.kind === "mock" ? " · mock, free" : ""}
                        {r.role ? ` · ${r.role.replace(/_/g, " ")}` : ""}
                      </div>
                      {!r.available ? (
                        <div className="text-[10.5px] text-warn">{r.unavailableReason ?? "unavailable"}</div>
                      ) : null}
                      {(r.modes.length > 0 ||
                        r.tiers.length > 0 ||
                        r.nativeAudio ||
                        (still && r.qualities.length > 0)) && (
                        <div className="mt-1 flex flex-wrap gap-1.5">
                          {still && r.qualities.length > 0 ? (
                            <select
                              aria-label={`${r.label} quality`}
                              data-testid="model-quality"
                              className="!w-auto text-[11px]"
                              value={c.quality ?? ""}
                              onChange={(e) =>
                                setChoice((s) => ({ ...s, [r.key]: { ...c, quality: e.target.value } }))
                              }
                            >
                              {r.qualities.map((q) => (
                                <option key={q.id} value={q.id}>
                                  {q.label} · {q.note}
                                  {q.id === r.defaultQuality ? " · Prism default" : ""}
                                </option>
                              ))}
                            </select>
                          ) : null}
                          {r.modes.length > 0 ? (
                            <select
                              aria-label={`${r.label} input mode`}
                              className="!w-auto text-[11px]"
                              value={c.mode ?? ""}
                              onChange={(e) =>
                                setChoice((s) => ({
                                  ...s,
                                  [r.key]: { ...c, mode: e.target.value as Choice["mode"] },
                                }))
                              }
                            >
                              <option value="keyframes">Keyframes (storyboard = first frame)</option>
                              <option value="references">References (frame becomes a reference)</option>
                            </select>
                          ) : null}
                          {r.tiers.length > 0 ? (
                            <select
                              aria-label={`${r.label} resolution tier`}
                              className="!w-auto text-[11px]"
                              value={c.tier ?? ""}
                              onChange={(e) =>
                                setChoice((s) => ({ ...s, [r.key]: { ...c, tier: e.target.value } }))
                              }
                            >
                              {r.tiers.map((t) => (
                                <option key={t} value={t}>
                                  {t}
                                </option>
                              ))}
                            </select>
                          ) : null}
                          {r.nativeAudio ? (
                            <label className="flex items-center gap-1 text-[11px] text-muted">
                              <input
                                type="checkbox"
                                checked={c.audio}
                                onChange={(e) =>
                                  setChoice((s) => ({ ...s, [r.key]: { ...c, audio: e.target.checked } }))
                                }
                              />
                              provider audio
                            </label>
                          ) : null}
                        </div>
                      )}
                    </td>
                    <td className="px-2 py-1.5" data-testid="model-eligibility">
                      {animate ? (
                        <Badge tone={v.status === "unsupported" ? "fail" : "pass"}>
                          {v.status === "unsupported" ? "Incompatible" : "Eligible"}
                        </Badge>
                      ) : (
                        <Badge tone={TONE[v.status]}>{v.statusLabel}</Badge>
                      )}
                      {v.adaptations.length > 0 ? (
                        <div className="mt-1 text-[10.5px] text-muted">{v.adaptations.join(" · ")}</div>
                      ) : null}
                      {v.blockers.length > 0 ? (
                        <div className="mt-1 text-[10.5px] text-fail" data-testid="model-why">
                          {v.blockers[0]}
                        </div>
                      ) : null}
                    </td>
                    {animate ? (
                      <>
                        <td className="px-2 py-1.5" data-testid="model-first-frame">
                          {v.animation?.exactFirstFrame ? "YES" : "NO"}
                        </td>
                        <td className="px-2 py-1.5 font-mono text-[11px] text-muted" data-testid="model-durations">
                          {msText(v.animation?.productionMs)} → {msText(v.animation?.providerMs)} →{" "}
                          {msText(v.animation?.deliveryMs)}
                          {v.durationUnverified ? (
                            <span className="text-warn"> · bounds unverified</span>
                          ) : null}
                        </td>
                        <td className="px-2 py-1.5 text-muted" data-testid="model-canvas">
                          {v.animation?.providerCanvas ?? "—"}
                          {v.animation?.productionFraming &&
                          v.animation.providerCanvas &&
                          v.animation.providerCanvas !== v.animation.productionFraming ? (
                            <span className="block text-[10.5px] text-faint">
                              Production Frame {v.animation.productionFraming} → provider{" "}
                              {v.animation.providerCanvas} → delivery back to {v.animation.productionFraming}
                            </span>
                          ) : null}
                        </td>
                        <td className="px-2 py-1.5 text-muted">{v.animation?.audioConditioning ?? "—"}</td>
                        <td className="px-2 py-1.5 text-muted" data-testid="model-native-audio">
                          {v.animation?.nativeAudio ? "on" : "off"}
                        </td>
                      </>
                    ) : (
                      <>
                        <td className="px-2 py-1.5 tabular-nums" data-testid="refs-used">
                          {v.referencesUsed.used}/{v.referencesUsed.total}
                        </td>
                        {still ? (
                          <td className="px-2 py-1.5 tabular-nums text-muted" data-testid="model-canvas">
                            {v.canvas ?? "—"}
                          </td>
                        ) : (
                          <td className="px-2 py-1.5 text-muted">
                            {v.duration}
                            {v.durationUnverified ? (
                              <span className="text-warn"> · bounds unverified</span>
                            ) : null}
                          </td>
                        )}
                        <td className="px-2 py-1.5 text-muted">{v.framing}</td>
                        {still ? null : <td className="px-2 py-1.5 text-muted">{v.audio}</td>}
                      </>
                    )}
                    <td className="px-2 py-1.5 text-right tabular-nums" data-testid="model-cost">
                      {r.kind === "mock" ? "free" : money(v.estimateUsd)}
                    </td>
                    {animate ? (
                      <td className="px-2 py-1.5 text-muted" data-testid="model-refs-omitted">
                        {v.animation?.referencesOmittedKeyframe
                          ? `${v.animation.referencesOmittedKeyframe} (represented by the Production Frame)`
                          : "none"}
                      </td>
                    ) : null}
                    <td className="px-2 py-1.5 text-muted" data-testid="model-history">
                      {r.history && r.history.reviewed > 0 ? (
                        <>
                          {r.history.approved + r.history.shortlisted}/{r.history.reviewed} liked
                          <div className="text-[10.5px] text-faint">
                            {r.recommendation.sample.similar} similar ·{" "}
                            {r.history.reliability.replace("_", " ")}
                          </div>
                        </>
                      ) : (
                        <span className="text-faint">no reviews yet</span>
                      )}
                    </td>
                    <td className="px-2 py-1.5">
                      <Badge tone={REC_TONE[r.recommendation.label] ?? "neutral"}>
                        {REC_TEXT[r.recommendation.label] ?? r.recommendation.label}
                      </Badge>
                      <div className="mt-0.5 text-[10.5px] text-faint">
                        confidence {r.recommendation.confidence}
                      </div>
                    </td>
                  </tr>
                  {open ? (
                    <tr className="border-b border-line bg-bg" data-testid="model-detail">
                      <td />
                      <td colSpan={animate ? 11 : still ? 8 : 9} className="px-2 py-2">
                        <div className="grid gap-3 md:grid-cols-3">
                          <div>
                            <div className="mb-1 text-[10.5px] uppercase tracking-wide text-muted">
                              What this model receives
                            </div>
                            <ul className="space-y-1">
                              {v.packaging.map((p, i) => (
                                <li key={i} className="flex items-start gap-1.5 text-[11.5px]">
                                  <Badge tone={PACK_TONE[p.state] ?? "neutral"}>
                                    {PACKAGING_LABELS[p.state]}
                                  </Badge>
                                  <span>
                                    <span className="text-fg">{p.label}</span>
                                    <span className="block text-[10.5px] text-faint">{p.detail}</span>
                                  </span>
                                </li>
                              ))}
                            </ul>
                          </div>
                          <div>
                            <div className="mb-1 text-[10.5px] uppercase tracking-wide text-muted">Why</div>
                            <ul className="list-disc space-y-0.5 pl-4 text-[11.5px]">
                              {r.recommendation.why.map((w, i) => (
                                <li key={`w${i}`}>{w}</li>
                              ))}
                              {r.recommendation.concerns.map((w, i) => (
                                <li key={`c${i}`} className="text-warn">
                                  {w}
                                </li>
                              ))}
                            </ul>
                          </div>
                          <div className="text-[11.5px] text-muted">
                            <div className="mb-1 text-[10.5px] uppercase tracking-wide">Cost and history</div>
                            <p>{v.estimateBasis ?? "No estimate."}</p>
                            {r.history && r.history.reviewed > 0 ? (
                              <p className="mt-1">
                                {r.history.reviewed} reviewed · {r.history.approved} good ·{" "}
                                {r.history.shortlisted} shortlisted · {r.history.rejected} rejected ·{" "}
                                {r.history.preferredWins} wins
                                {r.history.topRejectionReasons[0]
                                  ? ` · most common rejection: ${r.history.topRejectionReasons[0].tag.replace(/_/g, " ")}`
                                  : ""}
                              </p>
                            ) : null}
                            <p className="mt-1 text-faint">
                              Sample: {r.recommendation.sample.similar} similar shot(s), score{" "}
                              {r.recommendation.score ?? "n/a"} (advisory).
                            </p>
                          </div>
                        </div>
                      </td>
                    </tr>
                  ) : null}
                </RowFragment>
              );
            })}
          </tbody>
        </table>
      </div>

      <ActionForm
        action={createCandidateSet}
        successMessage="Candidate set created"
        quiet={false}
        className="space-y-2 border border-line bg-panel p-3"
        data-testid="candidate-form"
      >
        <input type="hidden" name="projectSlug" value={projectSlug} />
        <input type="hidden" name="shotId" value={shotId} />
        <input type="hidden" name="selections" value={selections} />
        <input type="hidden" name="generationPurpose" value={purpose} />
        <input type="hidden" name="preference" value={preference} />
        <input type="hidden" name="ackAll" value={ack ? "1" : "0"} />
        <input type="hidden" name="confirmedTotalUsd" value={paid.length > 0 ? String(totalRounded) : ""} />

        <div className="flex flex-wrap items-center gap-3">
          <span className="text-[11px] font-semibold uppercase tracking-wide text-muted">
            {still ? "Production Frame candidates" : animate ? "Animation candidates" : "Candidate set"}
          </span>
          <span data-testid="selected-count" className="text-[12px]">
            {selected.length} selected
          </span>
          <span data-testid="selected-total" className="text-[12px] tabular-nums">
            {paid.length === 0
              ? selected.length > 0
                ? "Estimated total: free (mock)"
                : "Estimated total: —"
              : `Estimated total (maximum): ${unknownCost ? "unknown" : money(totalRounded)}`}
          </span>
          {paid.length > 0 ? (
            <span className="text-[11px] text-faint">
              set ceiling {setCeilingUsd == null ? "not configured" : money(setCeilingUsd)}
            </span>
          ) : null}
        </div>
        <ul className="space-y-0.5 text-[11.5px]">
          {selectedViews.map((s) => (
            <li key={s.row.key} className="flex justify-between gap-3">
              <span>{s.row.label}</span>
              <span className="tabular-nums text-muted">
                {still && s.view.quality ? `${s.view.quality} · ` : ""}
                {s.row.kind === "mock" ? "free" : money(s.view.estimateUsd)}
              </span>
            </li>
          ))}
        </ul>
        {selected.length > maxCandidates ? (
          <div className="text-[11px] text-fail">At most {maxCandidates} candidates per set.</div>
        ) : null}
        {paidBlocked ? (
          <div className="text-[11px] text-fail" data-testid="paid-blocked">
            {!paidEnabled
              ? "Paid generation is switched off on this server."
              : "No candidate-set spend ceiling is configured on this server."}
          </div>
        ) : null}
        {overCeiling ? (
          <div className="text-[11px] text-fail">
            Total {money(totalRounded)} exceeds the set ceiling {money(setCeilingUsd)}.
          </div>
        ) : null}
        {allIgnored.length > 0 ? (
          <label className="flex items-start gap-1.5 text-[11.5px]">
            <input
              type="checkbox"
              checked={ack}
              onChange={(e) => setAck(e.target.checked)}
              data-testid="ack-all"
            />
            <span>
              I understand what each candidate will NOT use ({allIgnored.slice(0, 4).join("; ")}
              {allIgnored.length > 4 ? "; …" : ""}).
            </span>
          </label>
        ) : selected.length > 0 ? (
          <label className="flex items-start gap-1.5 text-[11.5px]">
            <input
              type="checkbox"
              checked={ack}
              onChange={(e) => setAck(e.target.checked)}
              data-testid="ack-all"
            />
            <span>I have reviewed what each selected model receives.</span>
          </label>
        ) : null}
        {paid.length > 0 ? (
          <label className="flex items-start gap-1.5 text-[11.5px]">
            <input
              type="checkbox"
              checked={confirmTotal}
              onChange={(e) => setConfirmTotal(e.target.checked)}
              data-testid="confirm-total"
            />
            <span>
              I confirm spending up to <span className="tabular-nums">{money(totalRounded)}</span> on this
              set. Nothing is generated until I press the button.
            </span>
          </label>
        ) : null}
        <div className="flex flex-wrap items-center gap-2">
          <input
            name="title"
            placeholder="Title (optional)"
            aria-label="Candidate set title"
            className="!w-56"
          />
          <input name="purpose" placeholder="Purpose (optional)" aria-label="Purpose" className="!w-64" />
          <Button type="submit" variant="primary" disabled={!canSubmit} data-testid="create-candidate-set">
            {paid.length > 0
              ? `Generate ${selected.length} ${noun}${selected.length === 1 ? "" : "s"}`
              : still || animate
                ? `Generate ${selected.length} free ${noun}${selected.length === 1 ? "" : "s"}`
                : `Create set (${selected.length})`}
          </Button>
        </div>
      </ActionForm>
    </div>
  );
}

function RowFragment({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}
